// Truth Table/State-Transition Table for TopModule:
// Inputs: clk (positive edge), reset (active high), d (8 bits)
// Outputs: q (8 bits)
//
// On reset (active high), q becomes 0 regardless of d.
// On positive edge of clk, q becomes d if reset is low.
//
// clk | reset | d[7:0] | q[7:0]
// ----|-------|--------|--------
//  0  |   0   |  xxxx  |  xxxx
//  1  |   0   |  d     |  d
//  1  |   1   |  xxxx  |  00000000

module TopModule (
    input  clk,
    input  reset,
    input  d,
    output q
);

    // Since d and q are 8 bits, we need to handle each bit separately
    // Using a generate block to instantiate 8 D flip-flops

    genvar i;
    wire [7:0] q_int;

    generate
        for (i = 0; i < 8; i = i + 1) begin : dff_gen
            DFF dff_inst (
                .clk(clk),
                .reset(reset),
                .d(d),
                .q(q_int[i])
            );
        end
    endgenerate

    assign q = q_int;

endmodule

