// Inputs: clk, shift_ena, count_ena, data
// Outputs: q (4 bits)
//
// Description:
// - On positive clock edge:
//   - If shift_ena is 1, data is shifted in (MSB first)
//   - If count_ena is 1, the current value is decremented
//   - If both are 1, behavior is undefined (no priority specified)
//
// State transitions are based on the combination of shift_ena and count_ena.

module TopModule (
    input  clk,
    input  shift_ena,
    input  count_ena,
    input  data,
    output reg [3:0] q
);

always @(posedge clk) begin
    if (shift_ena) begin
        q <= {data, q[3:1]};
    end else if (count_ena) begin
        q <= q - 1;
    end
end

endmodule

module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010
    // 7: 0111
    // 15: 1111
    // SOP expression: a'bc'd + a'bcd + abcd'

    assign out_sop = (!a & b & !c & d) | (!a & b & c & d) | (a & b & c & !d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000
    // 1: 0001
    // 4: 0100
    // 5: 0101
    // 6: 0110
    // 9: 1001
    // 10: 1010
    // 13: 1101
    // 14: 1110
    // POS expression: (a + b' + c' + d') * (a + b' + c + d') * (a + b + c' + d') * (a + b + c + d) * (a' + b + c + d)

    assign out_pos = (a | (!b | !c | !d)) &
                     (a | (!b | c | !d)) &
                     (a | (b | !c | !d)) &
                     (a | (b | c | d)) &
                     (!a | b | c | d);

endmodule

