    output [7:0] y,
    output [7:0] z
);

    // Concatenate all inputs and add two 1's at the end
    wire [31:0] output_data = {a, b, c, d, e, f, 2'b11};

    // Split the 32-bit output into four 8-bit vectors
    assign w = output_data[7:0];
    assign x = output_data[15:8];
    assign y = output_data[23:16];
    assign z = output_data[31:24];

