// State Transition Table for TopModule
// State | Next state in=0, Next state in=1 | Output
// A     | A, B                             | 0
// B     | C, B                             | 0
// C     | A, D                             | 0
// D     | C, B                             | 1

module TopModule (
    input  in,
    input  state,
    output next_state,
    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000
    // Output is 0 for all states except D (output is 1 when in state D)

    // Output logic: out = state[3] (since D is 4'b1000)
    assign out = state[3];

    // State transition logic (one-hot encoding)
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Using one-hot encoding, only one bit is 1 at a time

    // State A (4'b0001)
    // in=0: next_state = A (4'b0001)
    // in=1: next_state = B (4'b0010)
    // State A: next_state = (in ? 4'b0010 : 4'b0001)

    // State B (4'b0010)
    // in=0: next_state = C (4'b0100)
    // in=1: next_state = B (4'b0010)
    // State B: next_state = (in ? 4'b0010 : 4'b0100)

    // State C (4'b0100)
    // in=0: next_state = A (4'b0001)
    // in=1: next_state = D (4'b1000)
    // State C: next_state = (in ? 4'b1000 : 4'b0001)

    // State D (4'b1000)
    // in=0: next_state = C (4'b0100)
    // in=1: next_state = B (4'b0010)
    // State D: next_state = (in ? 4'b0010 : 4'b0100)

    // Combine all cases using state and in
    assign next_state = 
        (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) :
        (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) :
        (state == 4'b0100) ? (in ? 4'b1000 : 4'b0001) :
        (state == 4'b1000) ? (in ? 4'b0010 : 4'b0100) : 4'b0000;

endmodule

