    // Next state logic
    assign next_state = 
        (state == 4'b0001) ? (in ? 4'b0010 : 4'b0001) : // A
        (state == 4'b0010) ? (in ? 4'b0010 : 4'b0100) : // B
        (state == 4'b0100) ? (in ? 4'b0001 : 4'b1000) : // C
        (state == 4'b1000) ? (in ? 4'b0100 : 4'b0010) : // D
        4'b0000; // default case

    // Output logic (Moore machine)
    assign out = 
        (state == 4'b1000) ? 1 : 0;

endmodule

