    output out
);

    // State encoding: A=4'b0001, B=4'b0010, C=4'b0100, D=4'b1000

    // Output logic: out is 1 only when in state D
    assign out = state[3]; // D is 4'b1000, so state[3] is 1 when in state D

    // State transition logic
    // next_state is determined based on current state and input 'in'

    // For each state, determine next_state for in=0 and in=1
    // Use one-hot encoding to generate next_state

    // State A (state[0] is 1)
    // in=0: next_state = A (state[0])
    // in=1: next_state = B (state[1])
    assign next_state = 
        (state[0] && ~in) ? 4'b0001 : // A, in=0
        (state[0] &&  in) ? 4'b0010 : // A, in=1
        (state[1] && ~in) ? 4'b0100 : // B, in=0
        (state[1] &&  in) ? 4'b0010 : // B, in=1
        (state[2] && ~in) ? 4'b0001 : // C, in=0
        (state[2] &&  in) ? 4'b1000 : // C, in=1
        (state[3] && ~in) ? 4'b0100 : // D, in=0
        (state[3] &&  in) ? 4'b0010 : // D, in=1
        4'b0000; // default case

