module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output [255:0] q
);

    // Current state of the game
    reg [255:0] current_q;

    // Next state of the game
    reg [255:0] next_q;

    // Local variables for neighbor count
    reg [3:0] neighbors;

    // Function to compute the number of live neighbors for a given cell
    function [3:0] count_neighbors;
        input [255:0] grid;
        input [4:0] row;
        input [4:0] col;
        reg [3:0] count;

        // Define the 8 neighboring positions
        localparam NEIGHBOR_OFFSETS = {8{4'b0000}}; // 8-bit offset for each neighbor
        localparam NEIGHBOR_DIRECTIONS = 8'b11111111; // All 8 directions

        for (integer i = 0; i < 8; i = i + 1) begin
            integer r, c;
            r = row + (NEIGHBOR_DIRECTIONS[i] >> 3);
            c = col + (NEIGHBOR_DIRECTIONS[i] & 4'b0011);
            // Wrap around using modulo 16
            r = (r % 16) == 0 ? 15 : (r % 16);
            c = (c % 16) == 0 ? 15 : (c % 16);
            if (grid[(r * 16) + c]) count = count + 1;
        end
        count_neighbors = count;
    endfunction

    // Compute next state based on current state
    always @(posedge clk) begin
        if (load) begin
            current_q <= data;
        end else begin
            current_q <= next_q;
        end
    end

    // Compute next state
    always @(*) begin
        next_q = 256'b0;
        for (integer i = 0; i < 16; i = i + 1) begin
            for (integer j = 0; j < 16; j = j + 1) begin
                integer row = i;
                integer col = j;
                neighbors = count_neighbors(current_q, row, col);
                if (neighbors == 2) begin
                    next_q[(row * 16) + col] = current_q[(row * 16) + col];
                end else if (neighbors == 3) begin
                    next_q[(row * 16) + col] = 1'b1;
                end
            end
        end
    end

endmodule

