// Truth table for TopModule (simplified for state transition logic)
// Note: The actual state transition logic is implemented in the module below.
// The truth table for the Game of Life rules is not directly applicable here
// since it's a sequential logic circuit with a 16x16 toroidal grid.

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal registers for next state
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state based on current state (q)
    always @(*) begin
        next_q = 256'b0;
        integer i, j, x, y, count;
        reg [3:0] neighbors;

        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                // Calculate neighbors for cell (i, j)
                count = 0;
                for (x = -1; x <= 1; x = x + 1) begin
                    for (y = -1; y <= 1; y = y + 1) begin
                        if (x == 0 && y == 0) continue;
                        // Toroidal wrap around
                        integer row = (i + x + 16) % 16;
                        integer col = (j + y + 16) % 16;
                        if (q[row * 16 + col]) count = count + 1;
                    end
                end

                // Apply Game of Life rules
                if (count == 2) begin
                    next_q[i * 16 + j] = q[i * 16 + j];
                end else if (count == 3) begin
                    next_q[i * 16 + j] = 1;
                end else begin
                    next_q[i * 16 + j] = 0;
                end
            end
        end
    end

endmodule

