module TopModule (
    input  clock,
    input  a,
    output p,
    output q
);

    reg p_reg, q_reg, next_p, next_q;

    always @(posedge clock) begin
        p_reg <= next_p;
        q_reg <= next_q;
    end

    // Determine next state based on current state and input a
    assign next_p = (p_reg == 1'b0 && a == 1'b1) ? 1'b1 : (p_reg == 1'b1 && a == 1'b0) ? 1'b0 : p_reg;
    assign next_q = (q_reg == 1'b0 && a == 1'b1) ? 1'b1 : (q_reg == 1'b1 && a == 1'b0) ? 1'b0 : q_reg;

    assign p = p_reg;
    assign q = q_reg;

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum reg [1:0] {A, B, C, D, E} state_t;

state_t current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

// State transition logic
always @(*) begin
    next_state = current_state;
    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end
        B: begin
            next_state = C;
        end
        C: begin
            next_state = D;
        end
        D: begin
            next_state = E;
        end
        E: begin
            next_state = B;
        end
        default: next_state = A;
    endcase
end

// Output logic
always @(*) begin
    case (current_state)
        A: z = 1'b0;
        B: z = 1'b0;
        C: z = 1'b0;
        D: z = 1'b0;
        E: z = 1'b0;
        default: z = 1'b0;
    endcase
end

// Count logic for w input in states C, D, E
reg [2:0] w_count;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        w_count <= 3'b000;
    end else begin
        if (current_state == B) begin
            w_count <= {w_count[1:0], w};
        end
    end
end

// Set z to 1 if exactly two of the last three w's are 1
always @(*) begin
    case (current_state)
        E: begin
            if (w_count == 3'b110 || w_count == 3'b101 || w_count == 3'b011) begin
                z = 1'b1;
            end else begin
                z = 1'b0;
            end
        end
        default: z = 1'b0;
    endcase
end

endmodule

// State Transition Table for TopModule
// State | y   | Next State (Next y) | Transition Condition (w)
// A     | 000 | A                   | w=1
// A     | 000 | B                   | w=0
// B     | 001 | C                   | w=0
// B     | 001 | D                   | w=1
// C     | 010 | E                   | w=0
// C     | 010 | D                   | w=1
// D     | 011 | F                   | w=0
// D     | 011 | A                   | w=1
// E     | 100 | E                   | w=0
// E     | 100 | D                   | w=1
// F     | 101 | C                   | w=0
// F     | 101 | D                   | w=1

module TopModule (
    input  [2:0] y,
    input        w,
    output       Y1
);

    // State codes:
    // A = 000, B = 001, C = 010, D = 011, E = 100, F = 101

    // Next state logic for y[1]
    // Y1 is the second bit of the next state

    // Determine next state based on current state and input w
    // Then assign Y1 as the second bit of the next state

    // Current state decoding
    reg [2:0] next_y;

    always @(*) begin
        case ({y, w})
            3'b0000: next_y = 3'b000; // A -> A (w=1)
            3'b0001: next_y = 3'b001; // A -> B (w=0)
            3'b0010: next_y = 3'b010; // B -> C (w=0)
            3'b0011: next_y = 3'b011; // B -> D (w=1)
            3'b0100: next_y = 3'b100; // C -> E (w=0)
            3'b0101: next_y = 3'b011; // C -> D (w=1)
            3'b0110: next_y = 3'b101; // D -> F (w=0)
            3'b0111: next_y = 3'b000; // D -> A (w=1)
            3'b1000: next_y = 3'b100; // E -> E (w=0)
            3'b1001: next_y = 3'b011; // E -> D (w=1)
            3'b1010: next_y = 3'b010; // F -> C (w=0)
            3'b1011: next_y = 3'b011; // F -> D (w=1)
            default: next_y = 3'b000;
        endcase
    end

    // Output Y1 is the second bit of the next state
    assign Y1 = next_y[1];

endmodule

// Truth table for TopModule: State transition for Conway's Game of Life on a 16x16 toroidal grid
// Inputs:
//   clk: Clock signal
//   load: Load signal (active high)
//   data: 256-bit input data (initial state)
// Outputs:
//   q: 256-bit output (current state of the grid)

// The state of the grid is updated every clock cycle, with the new state computed based on the current state and the rules of the game.
// When load is high, the data is loaded into q on the next clock edge.

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal signal to hold the next state
    reg [255:0] next_q;

    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state based on current state (q)
    always @(*) begin
        next_q = 256'h0;

        for (integer i = 0; i < 16; i++) begin
            for (integer j = 0; j < 16; j++) begin
                // Current cell position in the 256-bit vector
                integer idx = i * 16 + j;

                // Determine the current cell value
                reg current_cell = q[idx];

                // Count the number of live neighbors
                integer neighbor_count = 0;

                // Check all 8 neighbors (toroidal grid)
                for (integer di = -1; di <= 1; di = di + 1) begin
                    for (integer dj = -1; dj <= 1; dj = dj + 1) begin
                        if (di == 0 && dj == 0) continue; // Skip the cell itself

                        integer ni = (i + di) % 16;
                        integer nj = (j + dj) % 16;
                        integer nidx = ni * 16 + nj;

                        if (q[nidx] == 1) neighbor_count = neighbor_count + 1;
                    end
                end

                // Apply the game rules
                if (neighbor_count < 2) begin
                    next_q[idx] = 1'b0;
                end else if (neighbor_count == 2) begin
                    next_q[idx] = current_cell;
                end else if (neighbor_count == 3) begin
                    next_q[idx] = 1'b1;
                end else begin
                    next_q[idx] = 1'b0;
                end
            end
        end
    end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal registers for next state
    reg [255:0] next_q;

    // Determine the number of live neighbors for each cell
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            // Compute next state
            next_q <= 256'b0;

            for (integer i = 0; i < 16; i++) begin
                for (integer j = 0; j < 16; j++) begin
                    // Current cell position in the 256-bit vector
                    integer pos = i * 16 + j;

                    // Count live neighbors
                    integer live_neighbors = 0;

                    // Check all 8 neighbors (toroidal grid)
                    for (integer dx = -1; dx <= 1; dx++) begin
                        for (integer dy = -1; dy <= 1; dy++) begin
                            if (dx == 0 && dy == 0) continue;

                            integer ni = (i + dx + 16) % 16;
                            integer nj = (j + dy + 16) % 16;
                            integer npos = ni * 16 + nj;

                            if (q[npos]) begin
                                live_neighbors += 1;
                            end
                        end
                    end

                    // Apply Conway's Game of Life rules
                    if (live_neighbors == 2) begin
                        next_q[pos] <= q[pos];
                    end else if (live_neighbors == 3) begin
                        next_q[pos] <= 1'b1;
                    end else begin
                        next_q[pos] <= 1'b0;
                    end
                end
            end

            q <= next_q;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State machine states
    typedef enum reg [2:0] {
        STATE_LOW,     // Below s[0]
        STATE_MID1,    // Between s[1] and s[0]
        STATE_MID2,    // Between s[2] and s[1]
        STATE_HIGH     // Above s[2]
    } state_t;

    state_t current_state, next_state;
    reg [2:0] prev_sensors;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            prev_sensors <= 3'b111; // All sensors asserted (low level)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            current_state <= next_state;
            prev_sensors <= s;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;
        case (current_state)
            STATE_LOW: begin
                if (s[0]) begin
                    next_state = STATE_MID1;
                end else begin
                    next_state = STATE_LOW;
                end
            end
            STATE_MID1: begin
                if (s[1]) begin
                    next_state = STATE_MID2;
                end else if (s[0]) begin
                    next_state = STATE_MID1;
                end else begin
                    next_state = STATE_LOW;
                end
            end
            STATE_MID2: begin
                if (s[2]) begin
                    next_state = STATE_HIGH;
                end else if (s[1]) begin
                    next_state = STATE_MID2;
                end else if (s[0]) begin
                    next_state = STATE_MID1;
                end else begin
                    next_state = STATE_LOW;
                end
            end
            STATE_HIGH: begin
                if (!s[2]) begin
                    next_state = STATE_MID2;
                end else begin
                    next_state = STATE_HIGH;
                end
            end
        endcase
    end

    // Output logic based on current state and sensor change
    always @(*) begin
        fr2 = 1'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = 1'b0;

        if (current_state == STATE_LOW) begin
            fr2 = 1'b1;
            fr1 = 1'b1;
            fr0 = 1'b1;
            dfr = 1'b0;
        end else if (current_state == STATE_MID1) begin
            fr0 = 1'b1;
            fr1 = 1'b1;
            dfr = (prev_sensors < s) ? 1'b1 : 1'b0;
        end else if (current_state == STATE_MID2) begin
            fr0 = 1'b1;
            dfr = (prev_sensors < s) ? 1'b1 : 1'b0;
        end else if (current_state == STATE_HIGH) begin
            // No nominal flow rate, flow rate is zero
            fr2 = 1'b0;
            fr1 = 1'b0;
            fr0 = 1'b0;
            dfr = 1'b0;
        end
    end

endmodule

module TopModule (
    input  y,
    input  w,
    output Y1
);

    // State codes: y = 000 (A), 001 (B), 010 (C), 011 (D), 100 (E), 101 (F)
    // y is a 3-bit input, but we only need to implement next-state logic for y[1]

    // Next-state logic for y[1] based on current state (y) and input w
    // y[1] is the second bit of the 3-bit state code

    // Current state bits
    wire y0 = y[0];
    wire y1 = y[1];
    wire y2 = y[2];

    // Next state for y[1]
    wire next_y1;

    // State transitions:
    // A (000) --0--> B (001), --1--> A (000)
    // B (001) --0--> C (010), --1--> D (011)
    // C (010) --0--> E (100), --1--> D (011)
    // D (011) --0--> F (101), --1--> A (000)
    // E (100) --0--> E (100), --1--> D (011)
    // F (101) --0--> C (010), --1--> D (011)

    // Determine next state based on current state and input w
    always @(*) begin
        case ({y2, y1, y0})
            3'b000: // A
                if (w == 1'b0) next_y1 = 1'b0; // B (001) -> y1 = 0
                else        next_y1 = 1'b0; // A (000) -> y1 = 0
            3'b001: // B
                if (w == 1'b0) next_y1 = 1'b1; // C (010) -> y1 = 1
                else        next_y1 = 1'b1; // D (011) -> y1 = 1
            3'b010: // C
                if (w == 1'b0) next_y1 = 1'b0; // E (100) -> y1 = 0
                else        next_y1 = 1'b1; // D (011) -> y1 = 1
            3'b011: // D
                if (w == 1'b0) next_y1 = 1'b0; // F (101) -> y1 = 0
                else        next_y1 = 1'b0; // A (000) -> y1 = 0
            3'b100: // E
                if (w == 1'b0) next_y1 = 1'b0; // E (100) -> y1 = 0
                else        next_y1 = 1'b1; // D (011) -> y1 = 1
            3'b101: // F
                if (w == 1'b0) next_y1 = 1'b1; // C (010) -> y1 = 1
                else        next_y1 = 1'b1; // D (011) -> y1 = 1
            default: next_y1 = 1'b0;
        endcase
    end

    // Output Y1 is y[1]
    assign Y1 = next_y1;

endmodule

module TopModule (
    input  clock,
    input  a,
    output p,
    output q
);

reg p_reg, q_reg;

always @(posedge clock) begin
    if (a) begin
        p_reg <= 1'b1;
        q_reg <= 1'b0;
    end else begin
        if (p_reg) begin
            p_reg <= 1'b0;
            q_reg <= 1'b1;
        end else begin
            p_reg <= 1'b0;
            q_reg <= 1'b0;
        end
    end
end

assign p = p_reg;
assign q = q_reg;

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    // Check for bump left or right
                    if (bump_left) begin
                        next_state = WALK_RIGHT;
                    end else if (bump_right) begin
                        next_state = WALK_RIGHT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (bump_left) begin
                        next_state = WALK_LEFT;
                    end else if (bump_right) begin
                        next_state = WALK_LEFT;
                    end else if (!ground) begin
                        next_state = FALLING;
                    end else if (dig) begin
                        next_state = DIGGING;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                DIGGING: begin
                    if (ground) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = FALLING;
                    end
                end

                default: next_state = WALK_LEFT;
            endcase

            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end

                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end

                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end

                default: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
            endcase
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate output (fr2)
// fr1 - nominal flow rate output (fr1)
// fr0 - nominal flow rate output (fr0)
// dfr - supplemental flow valve (active when previous level was lower than current)

// State: Represents the previous water level (based on sensor input)
// State transitions are based on current sensor input and previous state

// State Encoding:
// 0: No sensors asserted (water level below s[0])
// 1: Only s[0] asserted (water level between s[1] and s[0])
// 2: s[0] and s[1] asserted (water level between s[2] and s[1])
// 3: All sensors asserted (water level above s[2])

// Transition Table:
// Current State | s[2:0] | Next State | fr2 | fr1 | fr0 | dfr
// 0            | 000    | 0         | 1   | 1   | 1   | 0
// 0            | 001    | 1         | 0   | 1   | 1   | 1
// 0            | 010    | 2         | 0   | 0   | 1   | 1
// 0            | 011    | 3         | 0   | 0   | 0   | 1
// 1            | 000    | 0         | 1   | 1   | 1   | 0
// 1            | 001    | 1         | 0   | 1   | 1   | 1
// 1            | 010    | 2         | 0   | 0   | 1   | 1
// 1            | 011    | 3         | 0   | 0   | 0   | 1
// 2            | 000    | 0         | 1   | 1   | 1   | 0
// 2            | 001    | 1         | 0   | 1   | 1   | 1
// 2            | 010    | 2         | 0   | 0   | 1   | 1
// 2            | 011    | 3         | 0   | 0   | 0   | 1
// 3            | 000    | 0         | 1   | 1   | 1   | 0
// 3            | 001    | 1         | 0   | 1   | 1   | 1
// 3            | 010    | 2         | 0   | 0   | 1   | 1
// 3            | 011    | 3         | 0   | 0   | 0   | 1

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State register
    reg [1:0] state;

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00; // Reset to state 0 (no sensors asserted)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            case (state)
                2'b00: begin // Previous state: no sensors asserted
                    if (s == 3'b000) begin
                        state <= 2'b00;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end else if (s == 3'b001) begin
                        state <= 2'b01;
                        fr2 <= 1'b0;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end else if (s == 3'b010) begin
                        state <= 2'b10;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b1;
                    end else if (s == 3'b011) begin
                        state <= 2'b11;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b1;
                    end
                end

                2'b01: begin // Previous state: only s[0] asserted
                    if (s == 3'b000) begin
                        state <= 2'b00;
                        fr2 <= 1'b1;
                        fr1 <= 1'b1;
                        fr0 <= 1'b1;
