module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    typedef enum reg [1:0] {
        S0 = 2'b00, // walk_left
        S1 = 2'b01, // walk_right
        S2 = 2'b10, // falling
        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        walk_left = 1'b0;
        walk_right = 1'b0;
        aaah = 1'b0;
        digging = 1'b0;

        case (current_state)
            S0: begin // walk_left
                if (ground) begin
                    if (dig) begin
                        next_state = S3;
                        digging = 1'b1;
                    end else if (bump_left || bump_right) begin
                        next_state = S1;
                        walk_right = 1'b1;
                    end else if (!ground) begin
                        next_state = S2;
                        aaah = 1'b1;
                    end
                end
            end

            S1: begin // walk_right
                if (ground) begin
                    if (dig) begin
                        next_state = S3;
                        digging = 1'b1;
                    end else if (bump_left || bump_right) begin
                        next_state = S0;
                        walk_left = 1'b1;
                    end else if (!ground) begin
                        next_state = S2;
                        aaah = 1'b1;
                    end
                end
            end

            S2: begin // falling
                if (ground) begin
                    next_state = S0;
                    walk_left = 1'b1;
                end else if (dig) begin
                    next_state = S2;
                    digging = 1'b1;
                end
            end

            S3: begin // digging
                if (ground) begin
                    if (dig) begin
                        next_state = S3;
                        digging = 1'b1;
                    end else if (!ground) begin
                        next_state = S2;
                        aaah = 1'b1;
                    end
                end
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state based on previous sensor inputs
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (sensor change)
            if (current_state > previous_state) begin
                dfr <= 1'b1;
            end
        end
    end
endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state based on current state and inputs
            case (current_state)
                WALK_LEFT: begin
                    if (!ground) begin
                        next_state <= FALLING;
                        was_falling <= 1'b1;
                    end else if (dig) begin
                        next_state <= DIGGING;
                    end else if (bump_right) begin
                        next_state <= WALK_RIGHT;
                    end else begin
                        next_state <= WALK_LEFT;
                    end
                end

                WALK_RIGHT: begin
                    if (!ground) begin
                        next_state <= FALLING;
                        was_falling <= 1'b1;
                    end else if (dig) begin
                        next_state <= DIGGING;
                    end else if (bump_left) begin
                        next_state <= WALK_LEFT;
                    end else begin
                        next_state <= WALK_RIGHT;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        next_state <= WALK_LEFT;
                        was_falling <= 1'b0;
                    end else begin
                        next_state <= FALLING;
                    end
                end

                DIGGING: begin
                    if (!ground) begin
                        next_state <= FALLING;
                        was_falling <= 1'b1;
                    end else begin
                        next_state <= WALK_LEFT;
                    end
                end
            endcase

            current_state <= next_state;
        end
    end

    // Output logic
    always @(posedge clk) begin
        if (current_state == FALLING) begin
            aaah <= 1'b1;
            digging <= 1'b0;
            walk_left <= 1'b0;
            walk_right <= 1'b0;
        end else if (current_state == DIGGING) begin
            digging <= 1'b1;
            walk_left <= 1'b0;
            walk_right <= 1'b0;
        end else begin
            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end
            aaah <= 1'b0;
            digging <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 = below s[0], 1 = between s[1] and s[0], 2 = between s[2] and s[1], 3 = above s[2]
    reg [1:0] state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            prev_s <= 3'd0;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b1;
        end else begin
            // Determine current sensor state
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        // Above s[2]
                        state <= 2'd3;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b0;
                        dfr <= 1'b0;
                    end else begin
                        // Between s[2] and s[1]
                        state <= 2'd2;
                        fr2 <= 1'b0;
                        fr1 <= 1'b0;
                        fr0 <= 1'b1;
                        dfr <= 1'b0;
                    end
                end else begin
                    // Between s[1] and s[0]
                    state <= 2'd1;
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            end else begin
                // Below s[0]
                state <= 2'd0;
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Update previous sensor state
            prev_s <= s;
        end
    end

    // Check if the previous level was lower than the current level
    always @(posedge clk) begin
        if (s[2] && !prev_s[2]) begin
            dfr <= 1'b1;
        end else if (!s[2] && prev_s[2]) begin
            dfr <= 1'b0;
        end else if (s[1] && !prev_s[1]) begin
            dfr <= 1'b1;
        end else if (!s[1] && prev_s[1]) begin
            dfr <= 1'b0;
        end else if (s[0] && !prev_s[0]) begin
            dfr <= 1'b1;
        end else if (!s[0] && prev_s[0]) begin
            dfr <= 1'b0;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (prev_ground == 1'b1 && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == FALLING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                aaah <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_LEFT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (dig == 1'b1 && current_state == WALK_RIGHT && ground == 1'b1) begin
                next_state = DIGGING;
                digging <= 1'b1;
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b0) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (current_state == DIGGING && ground == 1'b1) begin
                next_state = WALK_LEFT;
                walk_left <= prev_direction;
                walk_right <= 1'b0;
                digging <= 1'b0;
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                if (bump_left && bump_right) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            if (current_state == WALK_LEFT) begin
                walk_left <= 1'b1;
                walk_right <= 1'b0;
            end else if (current_state == WALK_RIGHT) begin
                walk_left <= 1'b0;
                walk_right <= 1'b1;
            end else if (current_state == FALLING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end else if (current_state == DIGGING) begin
                walk_left <= 1'b0;
                walk_right <= 1'b0;
            end
        end
    end

endmodule

// Truth Table/State-Transition Table for TopModule
//
// Inputs:
// clk - clock
// reset - active-high synchronous reset
// s[2:0] - 3-bit sensor input (s[2] is highest, s[0] is lowest)
//
// Outputs:
// fr2 - nominal flow rate output (high when fr2 is asserted)
// fr1 - nominal flow rate output (high when fr1 is asserted)
// fr0 - nominal flow rate output (high when fr0 is asserted)
// dfr - supplemental flow valve (high when dfr is asserted)
//
// State Transition Logic:
// - When s[2] is high (water level above s[2]), flow rate is zero (fr2=0, fr1=0, fr0=0, dfr=0)
// - When s[0] is 0 and s[1] is 0 (water level below s[0]), flow rate is maximum (fr2=1, fr1=1, fr0=1, dfr=0)
// - When s[1] is high and s[0] is 0 (water level between s[1] and s[0]), flow rate is fr0, fr1 (fr2=0, fr1=1, fr0=1, dfr=0)
// - When s[1] is 0 and s[0] is high (water level between s[2] and s[1]), flow rate is fr0 (fr2=0, fr1=0, fr0=1, dfr=0)
// - If the sensor change indicates that the previous level was lower than the current level, dfr is set to 1
// - On reset, all outputs are set to 1 (fr2=1, fr1=1, fr0=1, dfr=0)

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State variables
    reg [2:0] prev_s;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
            prev_s <= 3'b000;
        end else begin
            // Determine current water level
            if (s[2]) begin
                // Water level above s[2]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end else if (s[1]) begin
                // Water level between s[2] and s[1]
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end else if (s[0]) begin
                // Water level between s[1] and s[0]
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end else begin
                // Water level below s[0]
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end

            // Check if previous level was lower than current level
            if (prev_s < s) begin
                dfr <= 1'b1;
            end else begin
                dfr <= 1'b0;
            end

            prev_s <= s;
        end
    end

endmodule

module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output reg fr2,
    output reg fr1,
    output reg fr0,
    output reg dfr
);

    // State definition: 0 - below s[0], 1 - between s[1] and s[0], 2 - between s[2] and s[1], 3 - above s[2]
    reg [1:0] current_state;
    reg [1:0] previous_state;

    // State transitions and output logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00; // Reset to state 0 (below s[0])
            previous_state <= 2'b00;
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            // Determine current state based on sensor inputs
            if (s[2]) begin
                if (s[1]) begin
                    if (s[0]) begin
                        current_state <= 2'b11; // Above s[2]
                    end else begin
                        current_state <= 2'b10; // Between s[2] and s[1]
                    end
                end else begin
                    current_state <= 2'b01; // Between s[1] and s[0]
                end
            end else begin
                current_state <= 2'b00; // Below s[0]
            end

            // Determine previous state (for detecting level increase)
            previous_state <= current_state;

            // Output logic based on current state
            case (current_state)
                2'b11: begin // Above s[2]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b0;
                    dfr <= 1'b0;
                end
                2'b10: begin // Between s[2] and s[1]
                    fr2 <= 1'b0;
                    fr1 <= 1'b0;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr2 <= 1'b0;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr2 <= 1'b1;
                    fr1 <= 1'b1;
                    fr0 <= 1'b1;
                    dfr <= 1'b0;
                end
            endcase

            // Check if previous level was lower than current level (to open dfr)
            if (previous_state < current_state) begin
                dfr <= 1'b1;
            end
        end
    end

endmodule

