        S3 = 2'b11  // digging
    } state_t;

    state_t current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= S0;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
        end else begin
            current_state <= next_state;
            walk_left <= (current_state == S0) ? 1 : (current_state == S1) ? 0 : (current_state == S2 || current_state == S3) ? 0 : 0;
            walk_right <= (current_state == S0) ? 0 : (current_state == S1) ? 1 : (current_state == S2 || current_state == S3) ? 0 : 0;
            aaah <= (current_state == S2) ? 1 : 0;
            digging <= (current_state == S3) ? 1 : 0;
        end
    end

    always @(*) begin
        next_state = current_state;

        case (current_state)
            S0: begin
                if (ground == 0) begin
                    next_state = S2;
                end else if (dig) begin
                    next_state = S3;
                end else begin
                    if (bump_left) next_state = S1;
                    if (bump_right) next_state = S1;
                end
            end

            S1: begin
                if (ground == 0) begin
                    next_state = S2;
                end else if (dig) begin
                    next_state = S3;
                end else begin
                    if (bump_left) next_state = S0;
                    if (bump_right) next_state = S0;
                end
            end

            S2: begin
                if (ground == 1) begin
                    next_state = S0;
                end
            end

            S3: begin
                if (ground == 0) begin
                    next_state = S2;
                end
            end

            default: next_state = S0;
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

    // Define states
    typedef enum reg [2:0] {
        WALK_LEFT,
        WALK_RIGHT,
        FALLING,
        DIGGING
    } state_t;

    state_t current_state, next_state;
    reg prev_ground;
    reg prev_direction;
    reg was_falling;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1'b1;
            walk_right <= 1'b0;
            aaah <= 1'b0;
            digging <= 1'b0;
            prev_ground <= 1'b1;
            prev_direction <= 1'b1;
            was_falling <= 1'b0;
        end else begin
            prev_ground <= ground;
            was_falling <= (current_state == FALLING);

            // Determine next state
            next_state = current_state;

            // Check for fall
            if (ground == 1'b0 && prev_ground == 1'b1) begin
                next_state = FALLING;
                aaah <= 1'b1;
                digging <= 1'b0;
            end else if (ground == 1'b1 && prev_ground == 1'b0) begin
                // Ground reappeared, resume walking
                if (was_falling) begin
                    next_state = WALK_LEFT;
                    walk_left <= prev_direction;
                    walk_right <= ~prev_direction;
                    aaah <= 1'b0;
                end
            end else if (dig) begin
                if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                    if (ground == 1'b1 && prev_ground == 1'b1) begin
                        next_state = DIGGING;
                        digging <= 1'b1;
                        walk_left <= 1'b0;
                        walk_right <= 1'b0;
                    end
                end
            end else if (current_state == WALK_LEFT || current_state == WALK_RIGHT) begin
                // Check for bump
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                end
            end

            // Update state and outputs
            current_state <= next_state;

            // Update outputs based on state
            case (current_state)
                WALK_LEFT: begin
                    walk_left <= 1'b1;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                WALK_RIGHT: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b1;
                    aaah <= 1'b0;
                    digging <= 1'b0;
                end
                FALLING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b1;
                    digging <= 1'b0;
                end
                DIGGING: begin
                    walk_left <= 1'b0;
                    walk_right <= 1'b0;
                    aaah <= 1'b0;
                    digging <= 1'b1;
                end
            endcase
        end
    end

endmodule
